  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Propagates water from the SOURCE up to a given distance using BFS, marking connected pipes as filled.
   * 2. Algorithm: 
   *    - Initialize BFS queue with (sourceCell.coord, 0), empty visited set, and new_filled_count = 0.
   *    - While queue not empty AND current_dist < distance:
   *        - Dequeue (coord, d). Mark coord as visited.
   *        - If current cell is not filled: mark filled, add coord to filledTiles, increment new_filled_count.
   *        - For each dir in current_cell.connections():
   *            - neighborCoord = coord.add(Pa19Helper.getOffset(dir))
   *            - neighborCell = cell[neighborCoord.row][neighborCoord.col]
   *            - If neighborCell is valid, not visited, and Pa19Helper.getOpposite(dir) is in neighborCell.connections():
   *                - Enqueue (neighborCoord, d+1).
   *    - Assign new_filled_count to prevFilledTiles.
   * 3. Related Features: sourceCell, cell[], filledTiles, prevFilledTiles, rows, cols
   * 4. Related Classes: Coordinate, TerminationCell, FillableCell, Pipe, Direction, Pa19Helper
   * 5. Input: int distance, maximum propagation steps from source (>=0).
   * 6. Output: void
   * 7. Pre-condition: sourceCell exists, distance is a non-negative integer.
   * 8. Post-condition: All reachable pipes within distance are marked filled, filledTiles list updated, and prevFilledTiles reflects the count of newly filled tiles for loss detection.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (getSourceCell() == null) {
      this.prevFilledTiles = 0;
      return;
    }
    
    Queue<Coordinate> queue = new ArrayDeque<>();
    Queue<Integer> distQueue = new ArrayDeque<>();
    Set<Coordinate> visited = new HashSet<>();
    
    Coordinate startCoord = getSourceCell().getCoord();
    queue.offer(startCoord);
    distQueue.offer(0);
    visited.add(startCoord);
    
    int newFilledCount = 0;
    Cell[][] grid = getCell();
    int numRows = getRows();
    int numCols = getCols();
    
    Pa19Helper pa19Helper = new Pa19Helper();
    
    while (!queue.isEmpty()) {
      Coordinate c = queue.poll();
      int d = distQueue.poll();
      
      if (d > distance) {
        break;
      }
      
      Cell currentCell = grid[c.getRow()][c.getCol()];
      if (currentCell instanceof FillableCell && ((FillableCell) currentCell).getPipe() != null && !((FillableCell) currentCell).getPipe().isFilled()) {
        ((FillableCell) currentCell).getPipe().setFilled(true);
        this.filledTiles.add(c);
        newFilledCount++;
      }
      
      if (d < distance && currentCell instanceof FillableCell && ((FillableCell) currentCell).getPipe() != null) {
        for (Direction dir : ((FillableCell) currentCell).getPipe().getConnections()) {
          Coordinate offset = pa19Helper.getOffset(dir);
          Coordinate neighborC = c.add(offset);
          
          if (neighborC.getRow() >= 0 && neighborC.getRow() < numRows &&
              neighborC.getCol() >= 0 && neighborC.getCol() < numCols) {
            
            Cell neighborCell = grid[neighborC.getRow()][neighborC.getCol()];
            if (neighborCell != null && !visited.contains(neighborC)) {
              Direction oppositeDir = pa19Helper.getOpposite(dir);
              if (neighborCell instanceof FillableCell && ((FillableCell) neighborCell).getPipe() != null && ((FillableCell) neighborCell).getPipe().getConnections().contains(oppositeDir)) {
                visited.add(neighborC);
                queue.offer(neighborC);
                distQueue.offer(d + 1);
              }
            }
          }
        }
      }
    }
    this.prevFilledTiles = newFilledCount;
  }

